package com.example.auth;
import static org.junit.jupiter.api.Assertions.*;
import com.example.auth.company.*;import com.example.auth.entity.*;import com.example.auth.common.ApiException;import jakarta.persistence.EntityManager;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.transaction.annotation.Transactional;
@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:web-settings;MODE=MySQL;DB_CLOSE_DELAY=-1") @Transactional
class SettingsTest {
 @Autowired EntityManager em;@Autowired SettingsService settings;@Autowired com.example.auth.service.AuthService auth;
 @MockitoBean com.example.auth.integration.BranchDirectory branches;
 Account admin,teacher,student,sa;
 Account create(String name,Role role,Long... ids){var a=Account.builder().username(name).password("hash").role(role).status(true).branchId(ids.length>0?ids[0]:null).build();em.persist(a);for(Long id:ids){var b=new AccountBranch();b.setAccount(a);b.setBranchId(id);b.setStatus(true);b.setAssignedAt(LocalDateTime.now());a.getBranchAssignments().add(b);em.persist(b);}return a;}
 @BeforeEach void setup(){sa=create("sa-settings",Role.SUPER_ADMIN);em.persist(SuperAdmin.builder().account(sa).fullName("SA").build());admin=create("admin-settings",Role.ADMIN,1L,2L);em.persist(Admin.builder().account(admin).fullName("Admin").build());teacher=create("teacher-settings",Role.TEACHER,1L);em.persist(Teacher.builder().account(teacher).fullName("Teacher").build());student=create("student-settings",Role.STUDENT);em.flush();}
 @Test void preferencesArePerAccountAndFirstSaveRejectsStaleDefault(){var p=settings.preferences(admin.getUsername());assertEquals(10,p.getPageSize());var saved=settings.save(admin.getUsername(),new SettingsService.PreferencesRequest(0L,true,20,"day",2L));assertEquals(1,saved.getVersion());assertEquals(10,settings.preferences(teacher.getUsername()).getPageSize());assertThrows(ApiException.class,()->settings.save(admin.getUsername(),new SettingsService.PreferencesRequest(0L,false,10,"week",null)));}
 @Test void branchAndPreferenceValuesAreValidated(){assertThrows(ApiException.class,()->settings.save(teacher.getUsername(),new SettingsService.PreferencesRequest(0L,false,20,"week",2L)));assertThrows(ApiException.class,()->settings.save(teacher.getUsername(),new SettingsService.PreferencesRequest(0L,false,999,"week",null)));assertThrows(ApiException.class,()->settings.save(teacher.getUsername(),new SettingsService.PreferencesRequest(0L,false,20,"month",null)));assertThrows(ApiException.class,()->settings.preferences(student.getUsername()));}
 @Test void revokedBranchClearsDefault(){settings.save(admin.getUsername(),new SettingsService.PreferencesRequest(0L,true,20,"week",2L));auth.assignBranches(admin.getId(),new com.example.auth.dto.BranchAssignmentsRequest(List.of(1L),1L),sa.getUsername());assertNull(settings.preferences(admin.getUsername()).getDefaultBranchId());assertEquals(2,settings.preferences(admin.getUsername()).getVersion());}
 @Test void onlySuperadminCanEditPublicCompanyProfile(){var p=em.find(CompanyProfile.class,1L);if(p==null){p=new CompanyProfile();p.setId(1L);em.persist(p);em.flush();}long v=p.getVersion();var request=new SettingsService.ProfileRequest(v,"Center","https://example.com/logo.png","Address","contact@example.com","0900000000");assertThrows(ApiException.class,()->settings.profile(admin.getUsername(),request));settings.profile(sa.getUsername(),request);assertEquals("Center",settings.profile(teacher.getUsername()).getName());assertThrows(ApiException.class,()->settings.profile(sa.getUsername(),request));}
 @Test void unsafeLogoIsRejected(){assertThrows(ApiException.class,()->settings.profile(sa.getUsername(),new SettingsService.ProfileRequest(0L,"Center","javascript:alert(1)",null,null,null)));}
}
